template <typename T>
void log_values(T val) { /* Base case processing */ }

template <typename T, typename... Args>
void log_values(T head, Args... tail) {
    // Head processing (e.g., printing the current argument)
    // ...
    log_values(tail...); // Recursive call: Pack expansion
}

template <typename... Nums>
auto calculate_sum(Nums... args) {
    // C++17 Fold Expression: (Initial value + Arg1 + Arg2 + ...)
    return (args + ... + 0); 
}

// Common pattern: applying a function to all elements
template <typename F, typename... Args>
void apply_to_all(F f, Args&&... args) {
    // Sequence comma operator ensures execution order
    ((f(std::forward<Args>(args))), ...); 
}
